import {circuitThumbnail,mountLibrary3D,closeLibrary3D} from './library-3d.mjs';
import {circuits,circuitSvg} from './circuit-library.mjs';
export const curriculum=[
 {title:'Orientarte en un circuito',skill:'Conexiones y referencias',ids:[0,1,8,9,10,23],intro:'Un esquema describe conexiones, no posiciones físicas. Dos puntos con el mismo nombre de red pertenecen al mismo nodo aunque estén separados en el dibujo.',steps:['Localiza entrada de energía, referencia y salida.','Sigue una sola red: anota sus terminales antes de saltar de componente.','Distingue cruzar una línea de conectar un nodo; confirma puntos de unión y etiquetas.'],links:['divider','pullup','pulldown']},
 {title:'Medir con una hipótesis',skill:'Medición y cálculo',ids:[2,11,13,21,22,24,30],intro:'Toda tensión es una diferencia entre dos puntos. Antes de colocar las puntas escribe la referencia, el estado de alimentación y el valor que esperas.',steps:['Predice el resultado con Ohm o un divisor sencillo.','Escoge V con alimentación; Ω o continuidad sin alimentación.','Compara el resultado y explica qué conexión respalda tu hipótesis.'],links:['divider','led','shunt']},
 {title:'Entender señales y estados',skill:'Funcionamiento',ids:[3,4,5,7,14,16,17,18,19,20,26,27,28],intro:'Para entender un circuito, compáralo en dos estados. Sigue por separado el camino de energía y el camino de control; observa qué cambia y qué permanece igual.',steps:['Define entrada baja/alta, contacto abierto/cerrado o antes/después.','Sigue la señal hasta el elemento que controla la carga.','En un condensador, diferencia el instante inicial del régimen permanente.'],links:['rc-low','rc-high','mosfet','pullup']},
 {title:'Reconocer bloques',skill:'Lectura funcional',ids:[15,32,33,34,35,36,37],intro:'La forma de un componente es una pista inicial. Su función se demuestra por sus conexiones: una resistencia puede limitar corriente, fijar un nivel, medir corriente o realimentar.',steps:['Empieza en los conectores y separa alimentación, entrada, control y carga.','Busca familias: bobina con regulador; transistor junto a carga; RC delante de una entrada.','Confirma los terminales y las redes antes de asignar un bloque.'],links:['buck','ldo','decoupling','sensor','relay']},
 {title:'Diagnosticar por evidencias',skill:'Diagnóstico',ids:[6,12,25,29,31],intro:'Una medida inesperada no identifica por sí sola un componente averiado. Elige una segunda medida que distinga entre dos causas posibles.',steps:['Registra primero el circuito correcto y sus condiciones.','Introduce una avería y compara la misma pareja de puntos.','Explica qué hipótesis descarta tu medida y cuál sigue pendiente.'],links:['mosfet','relay','comparator','buffer']},
 {title:'Pasar a placas complejas',skill:'Transferencia a placas',ids:Array.from({length:20},(_,i)=>38+i),intro:'En placas multicapa no puedes deducir todas las conexiones mirando una cara. Combina bloques, esquema, etiquetas de red, vías y puntos accesibles.',steps:['Delimita un bloque y su alimentación en ordenador, TV, lavadora, smartphone o tablet.','Marca energía y referencia con colores distintos y sigue las vías al cambiar de cara o capa.','Anota una predicción con puntos y condiciones; diferencia conectividad de simulación eléctrica.'],links:['charge','buck','sensor','noninv','inv']}
];
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function nextMission(done){return curriculum.flatMap(m=>m.ids).find(i=>!done.has(i));}
export function matchingCircuits(query='',group='all',mode='all',progress={}){const q=query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return circuits.filter(c=>`${c.name} ${c.group} ${c.recognize}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)&&(group==='all'||c.group===group)&&(mode==='all'||mode==='favorites'&&progress[c.id]?.favorite||mode==='review'&&!progress[c.id]?.passed));}
export function mountAcademy({storage,missions,done,startMission,freeMode,setBoard,onTheme}){
 const $=id=>document.getElementById(id);let progress={},selected=0,currentCircuit=null;
 try{progress=JSON.parse(storage.getItem('circuitlab-library-v4')||'{}');if(!progress||Array.isArray(progress)||typeof progress!=='object')progress={};}catch{}
 const save=()=>{try{storage.setItem('circuitlab-library-v4',JSON.stringify(progress));}catch{}};
 const read=(k,d)=>{try{return storage.getItem(k)||d;}catch{return d;}};
 const write=(k,v)=>{try{storage.setItem(k,v);}catch{}};
 function show(page){if(!['home','projects','course','library','lab','scope'].includes(page))page='course';for(const p of ['home','projects','course','library','lab','scope']){if($(p+'Page'))$(p+'Page').hidden=p!==page;if($('nav'+p)){$('nav'+p).classList.toggle('active',p===page);$('nav'+p).setAttribute('aria-current',p===page?'page':'false');}}write('circuitlab-page-v4',page);document.dispatchEvent(new CustomEvent('circuitlab:page',{detail:page}));if(page==='course')refresh();}
 const launch=i=>{startMission(i);show('lab');$('labPage').scrollIntoView({behavior:'smooth',block:'start'});};
 function refresh(){const n=curriculum.flatMap(m=>m.ids).filter(i=>done.has(i)).length,passed=circuits.filter(c=>progress[c.id]?.passed).length;
 $('courseStats').innerHTML=`<div><strong>${n}<small>/58</small></strong><span>retos superados</span></div><div><strong>${passed}<small>/18</small></strong><span>conceptos comprobados</span></div><div><strong>13</strong><span>placas para explorar</span></div>`;
 const next=nextMission(done);$('resumeTitle').textContent=next===undefined?'Recorrido completado. Sigue practicando.':missions[next].title;$('resumeCourse').textContent=next===undefined?'Volver al banco →':'Continuar mi recorrido →';$('resumeCourse').onclick=()=>next===undefined?(freeMode(),show('lab')):launch(next);
 $('courseModules').innerHTML=curriculum.map((m,i)=>{const count=m.ids.filter(id=>done.has(id)).length;return `<button class="moduleCard ${i===selected?'selected':''}" data-module="${i}"><span class="moduleIndex">${String(i+1).padStart(2,'0')} ${count===m.ids.length?'✓':''}</span><h3>${m.title}</h3><p>${m.skill}</p><div class="academyBar"><i style="width:${count/m.ids.length*100}%"></i></div><small>${count} / ${m.ids.length} retos</small></button>`;}).join('');
 $('courseModules').querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.module);refresh();$('moduleLesson').scrollIntoView({behavior:'smooth',block:'start'});});renderModule();
 }
 function renderModule(){const m=curriculum[selected];$('moduleLesson').innerHTML=`<div class="lessonHeading"><div><p class="eyebrow">ETAPA ${selected+1} · SECUENCIA RECOMENDADA</p><h2>${m.title}</h2></div><span class="pill">Acceso libre a todas las etapas</span></div><p class="lessonLead">${m.intro}</p><ol class="learningSteps">${m.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="moduleColumns"><div><h3>Practica y comprueba</h3><div class="courseTasks">${m.ids.map(i=>`<button data-task="${i}"><span class="taskCheck ${done.has(i)?'checked':''}">${done.has(i)?'✓':'○'}</span><span>${esc(missions[i].title)}</span><span>↗</span></button>`).join('')}</div></div><div><h3>Reconoce estos patrones</h3>${m.links.map(id=>{const c=circuits.find(c=>c.id===id);return `<button class="patternLink" data-pattern="${id}"><span>${c.icon}</span>${c.name}<b>→</b></button>`;}).join('')}<div class="studyNote"><b>Para ganar destreza</b><p>Explica en voz alta: «Esta entrada llega aquí, este componente hace esto y esta medida lo demostraría». Repite una práctica sin mirar la pista.</p><small>El progreso registra retos comprobados; no sustituye una evaluación práctica presencial.</small></div></div></div>`;
 $('moduleLesson').querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>launch(Number(b.dataset.task)));$('moduleLesson').querySelectorAll('[data-pattern]').forEach(b=>b.onclick=()=>{show('library');openCircuit(b.dataset.pattern);});}
 function renderLibrary(){const list=matchingCircuits($('librarySearch').value,$('libraryGroup').value,$('libraryMode').value,progress);$('libraryCount').textContent=`${list.length} de ${circuits.length} circuitos`;
 $('circuitGrid').innerHTML=list.length?list.map(c=>`<button class="circuitCard" data-circuit="${c.id}"><div class="circuitThumb">${circuitThumbnail(c.kind)}</div><div class="circuitCardBody"><span class="eyebrow">${c.group} · NIVEL ${c.level}</span><h3>${c.name}</h3><p>${c.purpose}</p><div><span>${progress[c.id]?.passed?'✓ Concepto comprobado':'Estudiar circuito →'}</span><span>${progress[c.id]?.favorite?'★':''}</span></div></div></button>`).join(''):'<div class="emptyLibrary">No hay circuitos con estos filtros. Prueba otro término o selecciona «Todos».</div>';
 $('circuitGrid').querySelectorAll('[data-circuit]').forEach(b=>b.onclick=()=>openCircuit(b.dataset.circuit));}
 function openCircuit(id){document.dispatchEvent(new CustomEvent('circuitlab:circuit-open'));const c=circuits.find(x=>x.id===id);if(!c)return;currentCircuit=id;const p=progress[id]||{};$('circuitArticle').hidden=false;
 $('circuitArticle').innerHTML=`<div class="lessonHeading"><div><p class="eyebrow">${c.group} · PATRÓN ${circuits.indexOf(c)+1} / 18</p><h2>${c.name}</h2></div><div><button id="favoriteCircuit">${p.favorite?'★ Guardado':'☆ Guardar'}</button> <button id="closeCircuit" aria-label="Cerrar ficha de circuito">×</button></div></div><section id="circuit3d" class="library3d"></section><div class="articleColumns"><div class="articleDiagram">${circuitSvg(c.kind)}<p>Esquema didáctico de principio. Valores y pinout concretos deben comprobarse en la documentación del circuito.</p><div class="formula">${esc(c.formula)}</div></div><div><h3>Cómo reconocerlo</h3><p>${c.recognize}</p><h3>Qué función cumple</h3><p>${c.purpose}</p><h3>Sigue el recorrido</h3><ol>${c.path.map(s=>`<li>${s}</li>`).join('')}</ol></div></div><div class="measureCards"><div><span>01 · PUNTAS Y REFERENCIA</span><p>${c.measure}</p></div><div><span>02 · RESULTADO ESPERADO</span><p>${c.expected}</p></div><div><span>03 · UNA AVERÍA POSIBLE</span><p>${c.fault}</p></div></div><p class="circuitTrap"><b>Evita esta confusión:</b> ${c.trap}</p><section class="conceptQuiz"><p class="eyebrow">COMPRUEBA TU RAZONAMIENTO</p><h3>${c.quiz.q}</h3><div>${c.quiz.answers.map((a,i)=>`<button data-answer="${i}">${a}</button>`).join('')}</div><p id="conceptFeedback" role="status" aria-live="polite">${p.passed?'✓ Concepto comprobado anteriormente. Puedes volver a practicar.':'Elige una respuesta y justifica tu elección antes de comprobar.'}</p></section><div class="articleFooter"><button id="circuitInstruments">Osciloscopio y generador guiados →</button>${c.board?'<button id="practiceCircuit" class="academyPrimary">'+(c.mission!==undefined?'Abrir práctica relacionada':'Explorar placa relacionada')+' →</button>':'<span class="pill">Estudio de esquema · sin simulación asociada</span>'}<a href="${c.source}" target="_blank" rel="noopener noreferrer">Documentación técnica ↗</a></div>`;
 mountLibrary3D($('circuit3d'),c.kind);$('circuitInstruments').onclick=()=>document.dispatchEvent(new CustomEvent('circuitlab:instruments',{detail:{lesson:c.kind==='lowpass'?'corte':c.kind==='highpass'?'offset':'generador'}}));
 $('favoriteCircuit').onclick=()=>{progress[id]={...(progress[id]||{}),favorite:!progress[id]?.favorite};save();renderLibrary();openCircuit(id);};$('closeCircuit').onclick=()=>{$('circuitArticle').hidden=true;currentCircuit=null;closeLibrary3D();};
 $('circuitArticle').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.answer)===c.quiz.correct;progress[id]={...(progress[id]||{}),passed:ok,attempts:(progress[id]?.attempts||0)+1};save();$('conceptFeedback').textContent=(ok?'✓ Correcto. ':'Revisa tu razonamiento. ')+c.quiz.why;$('conceptFeedback').className=ok?'quizCorrect':'quizRetry';renderLibrary();refresh();});
 if(c.board)$('practiceCircuit').onclick=()=>{if(c.mission!==undefined)launch(c.mission);else{freeMode();setBoard(c.board);show('lab');}};
 $('circuitArticle').scrollIntoView({behavior:'smooth',block:'start'});
 }
 function theme(){const v=$('themeSelect').value,dark=v==='dark'||v==='system'&&globalThis.matchMedia?.('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';write('circuitlab-theme-v4',v);onTheme(dark);}
 for(const p of ['course','library','lab','scope'])$('nav'+p).onclick=()=>show(p);
 $('themeSelect').value=read('circuitlab-theme-v4','dark');$('themeSelect').onchange=theme;globalThis.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if($('themeSelect').value==='system')theme();});theme();
 $('libraryGroup').innerHTML='<option value="all">Todos los temas</option>'+[...new Set(circuits.map(c=>c.group))].map(g=>`<option>${g}</option>`).join('');$('libraryGroup').value='all';$('libraryMode').value='all';for(const id of ['librarySearch','libraryGroup','libraryMode'])$(id)[id==='librarySearch'?'oninput':'onchange']=renderLibrary;
 $('browseLibrary').onclick=()=>show('library');refresh();renderLibrary();show(read('circuitlab-page-v4','course'));return {refresh,show,openCircuit};
}
